shows={}
for k,v in L.items():
    for a,b,ty,i,d in v['segs']:
        if ty=='CLIP': shows.setdefault(i,[]).append((int(k),a,b))
assert set(shows)==set(C), (set(shows)^set(C))
out=['# Бриф реконструкций R01–R19\n']
tot=0
for i in sorted(C):
    c=C[i]; sh=sorted(shows[i]); mx=max(b-a for _,a,b in sh); ln=math.ceil(mx+1)
    c['len']=ln; tot+=ln
    n=lambda x:f"{x:.1f}".replace('.',',')
    where=' · '.join(f"гл. {k}: {n(a)}–{n(b)} ({n(b-a)} с)" for k,a,b in sh)
    out.append(f"### {i}. {c['scene']} — {ln} с\n")
    out.append(f"**Окна:** {where}. Длина файла = самое длинное окно + 1 с.\n")
    out.append(f"**Проверка эпохи:** {c['epoch']}\n")
    out.append(f"**Референс:** {c['ref']}\n")
    out.append("**Стартовый кадр (Nano Banana 2, 16:9, 2K):**\n")
    out.append("```\n"+c['img']+" "+PLAIN+" "+STYLE+"\n```\n")
    out.append(f"**Движение (Grok Imagine Video, {ln} с):**\n")
    out.append("```\n"+c['mov']+"\n```\n")
    out.append(f"**Кадр → движение:** {c['check']}\n")
open(f'{E}/brief.md','w').write('\n'.join(out))
print('clips',len(C),'sum of file lengths',tot)
